style.css:
@-moz-document domain("roblox.com") {
/* ? Background */
    body {
        background-image: url(https://i.pinimg.com/1200x/53/08/9d/53089d4fea49e50fe40dd94fea9b0820.jpg) !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* ✨ Main containers */
    .container-main,
    .content,
    .section-content {
        background-color: rgba(255, 240, 248, 0.85) !important;
        border-radius: 18px !important;
    }

    /* ? Top navigation bar */
    .navbar,
    .rbx-navbar {
        background-color:#fcf2bb !important;
    }

    /* ? Links */
    a {
        color: #c77dbb !important;
    }

    /* ☁️ Buttons */
    .btn-primary {
        background-color: #b8dcf5 !important;
        border-radius: 999px !important;
        border: none !important;
    }

    /* ⭐ Text */
    body, p, span {
        color: #fcf2bb !important;
    }
}
